/* PALETTE _________________________________________________________ */
:root {
	--pi-paper   : #f4e9d8;                  /* page base                  */
	--pi-ink     : #1d1712;                  /* titles, rules, line art    */
	--pi-text    : #54483e;                  /* body text: faded brown-grey, as in the mockups */
	--pi-faint   : #8a7b6b;                  /* captions, footers          */
	--pi-cap     : #3b3531;                  /* drop-cap letter: charcoal, sunk into its blot */

	/* The mockups set running text in a faded italic. It is the look, but it
	   is slower to read over a whole book; for upright text put
	       .page { --pi-text-style : normal; --pi-text : #2b231c; }
	   in the Style tab, or  \page {roman}  on single pages.               */
	--pi-text-style : italic;
	--pi-wash    : rgba(91, 83, 72, .11);    /* boxes, table zebra         */
	--pi-wash-2  : rgba(91, 83, 72, .2);

	/* artwork is multiplied into the paper so whites take on the parchment
	   and it reads as watercolour; set to  none / normal  to show it raw   */
	--pi-art-grade : sepia(.1) saturate(.94) contrast(1.02) brightness(1.03);
	--pi-art-blend : multiply;

	--HB_Color_Background            : var(--pi-paper);
	--HB_Color_Accent                : var(--pi-wash);
	--HB_Color_HeaderUnderline       : var(--pi-ink);
	--HB_Color_HorizontalRule        : var(--pi-ink);
	--HB_Color_HeaderText            : var(--pi-ink);
	--HB_Color_MonsterStatBackground : var(--pi-wash);
	--HB_Color_CaptionText           : var(--pi-faint);
	--HB_Color_WatercolorStain       : #6d655a;
	--HB_Color_Footnotes             : var(--pi-faint);
}


/* PAGE SURFACE ____________________________________________________ */
.page {
	padding          : 3.2cm 3.7cm 2.4cm;      /* wide side margins: they carry the marginalia */
	column-width     : 6cm;     /* PHB's 8cm minimum won't fit two columns inside the frame */
	column-gap       : .8cm;
	font-family      : 'IM Fell English', 'Georgia', serif;
	font-size        : .33cm;
	font-style       : var(--pi-text-style);
	color            : var(--pi-text);
	background-color : var(--pi-paper);
	background-image :
		var(--pi-burn),
		var(--pi-stains),
		radial-gradient(ellipse 70% 60% at 48% 42%, rgba(255, 250, 235, .35), transparent 70%),
		var(--pi-paper-tile);
	background-size     : 100% 100%, 100% 100%, 100% 100%, 512px 512px;
	background-repeat   : no-repeat, no-repeat, no-repeat, repeat;
	box-shadow          : none;
	-webkit-mask        : var(--pi-edge) 0 0 / 100% 100% no-repeat;
	mask                : var(--pi-edge) 0 0 / 100% 100% no-repeat;
}
.page:nth-child(even) {
	background-size     : 100% 100%, 130% 130%, 100% 100%, 512px 512px;
	background-position : 0 0, 100% 100%, 0 0, 190px 230px;
}
.page.untorn { -webkit-mask : none; mask : none; }
.page.roman  { --pi-text-style : normal; --pi-text : #2b231c; }

/* corners and crest: one overlay underneath the text.

   Both are switchable, for the whole book in the Style tab
       .page { --pi-frame : var(--pi-frame-thorn); }
   or per page on the \page line:   \page {frame-thorn, crest-skull}

   frames  classic · thorn · gothic · bone · occult (four different corners)
   crests  classic (default) · compass · skull · blades · beetle · none
   (planar-ink-lite.css carries only the classic frame and the compass
    and classic crests.)                                                  */
:root {
	--pi-frame      : var(--pi-frame-classic);
	--pi-crest      : var(--pi-crest-classic);
	--pi-crest-size : 246px 52px;
	--pi-crest-top  : 44px;
}
.page.frame-classic  { --pi-frame : var(--pi-frame-classic); }
.page.frame-thorn    { --pi-frame : var(--pi-frame-thorn); }
.page.frame-gothic   { --pi-frame : var(--pi-frame-gothic); }
.page.frame-bone     { --pi-frame : var(--pi-frame-bone); }
.page.frame-occult   { --pi-frame : var(--pi-frame-occult); }
.page.crest-compass  { --pi-crest : var(--pi-p-crest-compass); --pi-crest-size : 400px 114px; --pi-crest-top : 8px; }
.page.crest-classic  { --pi-crest : var(--pi-crest-classic);   --pi-crest-size : 246px 52px;  --pi-crest-top : 44px; }
.page.crest-skull    { --pi-crest : var(--pi-p-crest-skull);   --pi-crest-size : 420px 78px;  --pi-crest-top : 22px; }
.page.crest-blades   { --pi-crest : var(--pi-p-crest-blades);  --pi-crest-size : 400px 89px;  --pi-crest-top : 16px; }
.page.crest-beetle   { --pi-crest : var(--pi-p-crest-beetle);  --pi-crest-size : 260px 113px; --pi-crest-top : 6px; }
.page.crest-none     { --pi-crest : none; }

.page::before {
	content             : '';
	position            : absolute;
	inset               : 0;
	z-index             : -1;
	pointer-events      : none;
	background-image    : var(--pi-crest), var(--pi-frame);
	background-position : center var(--pi-crest-top), 0 0;
	background-size     : var(--pi-crest-size), 100% 100%;
	background-repeat   : no-repeat;
	opacity             : .88;      /* the frame is fine pen work: a shade under the title's black */
}

/* marginalia and ink splatter: a second overlay, dealt per page.
   Four layers, each on its own cycle (see the generated block above):

     left margin · right margin · foot of the page · ink splatter

   A margin holds anything from nothing to four things: a drawing, the
   pair of skulls, a column of signs and runes, a hanging charm, wherever
   they fall between the corner brackets. The foot gets a flat drawing or a
   row of signs beside the page number on five pages in seven. The cycles
   are 11, 13, 7 and 9 long, so no two pages in 9009 are dealt the same.

   On the \page line:
     roll-1 … roll-13   deal this page a different hand
     no-left / no-right / no-foot / no-splatter   leave one layer out
     mirror             swap the margins
     plain / no-scatter leave them all out                                */
.page::after {
	content             : '';
	display             : block;
	position            : absolute;
	inset               : 0;
	z-index             : -1;
	width               : auto;
	height              : auto;
	pointer-events      : none;
	background-image    : var(--pi-l-img), var(--pi-r-img), var(--pi-b-img), var(--pi-splat-img);
	background-position : var(--pi-l-pos), var(--pi-r-pos), var(--pi-b-pos), var(--pi-splat-pos);
	background-size     : var(--pi-l-size), var(--pi-r-size), var(--pi-b-size), var(--pi-splat-size);
	background-repeat   : no-repeat;
}
.page:nth-child(even)::after { transform : none; }      /* the PHB theme flips its footer accent on even pages */
.page.mirror::after { transform : scaleX(-1); }
.page:is(.plain, .bare, .no-scatter)::after { display : none; }
.page.bare::before { display : none; }
.page.no-left     { --pi-l-img : none; --pi-l-pos : 0 0; --pi-l-size : 0 0; }
.page.no-right    { --pi-r-img : none; --pi-r-pos : 0 0; --pi-r-size : 0 0; }
.page.no-splatter { --pi-splat-img : none; --pi-splat-pos : 0 0; --pi-splat-size : 0 0; }
/* a footnote sits in the same strip as the foot marginalia: it wins */
.page.no-foot,
.page:has(.footnote) { --pi-b-img : none; --pi-b-pos : 0 0; --pi-b-size : 0 0; }

/* The scatter lives in the outer 3.4cm of the page and the strip under the
   text, which the text never enters, and (as on the references) it is drawn
   over any art that bleeds out that far. It stands down only on a page
   where you place pieces by hand (below): once you place one, the page is
   yours. \page {scatter} brings it back regardless.                     */
.page:has(.marg)::after { display : none; }
.page.scatter::after { display : block; }

/* HAND-PLACED MARGINALIA  ·  any drawing from the scatter, placed where you
   want it, like Homebrewery's watercolour stains:

     {{marg,ram,top:14cm,left:.5cm}}
     {{marg,pend-moon,top:6.4cm,right:.4cm}}
     {{marg,sp3,bottom:2cm,left:9cm,width:30px}}
     {{marg,skull,top:20cm,left:.6cm,rotate:-12deg,flip}}

   Natural size unless you give a width (height follows). flip mirrors it;
   rotate:… turns it. The piece names are listed at the top of the sheet. */
.page .marg {
	position            : absolute;
	z-index             : -1;
	display             : block;
	width               : var(--marg-w, var(--marg-nat));
	height              : auto;
	margin              : 0;
	pointer-events      : none;
	background-image    : var(--marg-img);
	background-size     : 100% 100%;
	background-repeat   : no-repeat;
	-webkit-mask-image  : var(--pi-inkgrain);
	mask-image          : var(--pi-inkgrain);
	-webkit-mask-size   : 256px 256px;
	mask-size           : 256px 256px;
}
.page .marg.flip { transform : scaleX(-1); }

/* INK TEXTURE  ·  pen ink doesn't lay down flat: it skips over the tooth of
   the paper and drags in dry streaks. A seamless alpha tile breaks up the
   titles and every ink overlay the same way, which is most of what makes
   the reference pages read as drawn rather than printed.               */
.page::before,
.page::after,
.page :is(h1, h2),
.page .orn {
	-webkit-mask-image : var(--pi-inkgrain);
	mask-image         : var(--pi-inkgrain);
	-webkit-mask-size  : 256px 256px;
	mask-size          : 256px 256px;
	-webkit-mask-repeat: repeat;
	mask-repeat        : repeat;
}

/* FOOTER __________________________________________________________ */
.page .pageNumber,
.page:nth-child(even) .pageNumber {
	right       : 0;
	left        : 0;
	bottom      : 30px;
	width       : 1.4cm;
	margin      : 0 auto;
	font-family : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size   : .4cm;
	line-height : 18px;
	color       : var(--pi-ink);
	text-align  : center;
}
.page .footnote {
	right          : 3.7cm;
	bottom         : 1.4cm;
	width          : 8cm;
	font-family    : 'IM Fell English', serif;
	font-size      : .29cm;
	font-style     : italic;
	color          : var(--pi-faint);
	text-transform : none;
}
.page:nth-child(even) .footnote { left : 3.7cm; right : auto; }


/* TYPOGRAPHY ______________________________________________________ */
/* the PHB sets its sans (ScalySans) on tables, stat blocks and spell
   lists; in an old printed book those are set in the text face too    */
.page :is(table, .monster, .spellList) { font-family : 'IM Fell English', 'Georgia', serif; }
.page .monster h5,
.page table thead th                     { font-family : 'IM Fell English SC', serif; }
.page p                { line-height : 1.42em; }
.page p + p,
.page ul + p,
.page ol + p           { text-indent : 1.3em; }
.page p + p            { margin-top : .08cm; }      /* paragraphs are marked by the indent, as in the mockups, not by a gap */
.page strong           { color : var(--pi-ink); }
.page a                { color : var(--pi-ink); text-decoration : underline dotted; text-underline-offset : 2px; }

.page ul               { list-style-type : '–  '; }
.page li::marker       { color : var(--pi-ink); }

/* HEADINGS */
.page :is(h1, h2, h3, h4, h5, h6) {
	font-weight : normal;
	color       : var(--pi-ink);
	break-after : avoid;
}
.page h1 {
	margin         : 0 -.3cm .4cm;
	font-family    : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size      : var(--pi-title, 1.95cm);      /* \page {--pi-title:1.7cm} to fit a long title on one line */
	font-style     : normal;
	line-height    : 1em;
	letter-spacing : .015em;
	text-align     : center;
	text-transform : none;      /* as written: capitals tall, lowercase as small caps */
	/* the mockup lettering is a loaded brush; the traced face is a pen.
	   A hairline stroke in the ink colour puts the weight back.           */
	-webkit-text-stroke : .7px var(--pi-ink);
}
.page h1 + p::first-line { font-variant : normal; }
.page h2 {
	font-family    : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size      : .82cm;
	font-style     : normal;
	line-height    : 1.08em;
	text-transform : none;
	-webkit-text-stroke : .3px var(--pi-ink);
}
.page :is(h3, h4, h5, h6, table, .monster, .note, .toc, .kicker, .pageNumber, code) { font-style : normal; }
/* H3 and H4 are lettered in the same thorned hand as the titles, a size
   down each time, so the whole heading ladder is one pen: H1 the brush, H2
   the pen, H3 the pen over a thorn rule, H4 the pen alone at text height.
   (A typeset small-cap face here read as a label stuck on a drawn page.)
   H5 stays in Fell small caps: it is the run-in label of notes and boxes. */
.page h3 {
	margin-top     : .34cm;
	padding-bottom : .2cm;
	font-family    : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size      : .6cm;
	font-weight    : normal;
	line-height    : 1.05em;
	letter-spacing : .02em;
	text-transform : none;
	border-bottom  : 0;
	background     : var(--pi-rule) left bottom / 100% 6px no-repeat;
	-webkit-text-stroke : .2px var(--pi-ink);
}
.page h4 {
	margin-top     : .26cm;
	margin-bottom  : .04cm;
	font-family    : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size      : .47cm;
	font-weight    : normal;
	line-height    : 1.1em;
	letter-spacing : .03em;
	text-transform : none;
}
.page h5 {
	font-family    : 'IM Fell English SC', serif;
	font-size      : .33cm;
	font-weight    : normal;
	letter-spacing : .1em;
}

/* KICKER  ·  {{kicker SERIES}} above a title: heavy spaced capitals over
   a small diamond rule, as on the third mockup.
   {{kicker,plaque SERIES}} sets it on the thorned plaque instead
   (border-image keeps the plaque's ends intact and stretches its middle
   to the text, so any length of kicker fits).                          */
.page .kicker {
	display        : block;
	column-span    : all;
	width          : fit-content;
	min-width      : 4cm;
	margin         : 0 auto .12cm;
	padding        : 0 .2cm .26cm;
	font-family    : 'Cinzel', 'IM Fell English SC', serif;
	font-size      : .66cm;
	font-weight    : 900;
	line-height    : 1.05em;
	letter-spacing : .1em;
	text-transform : uppercase;
	color          : var(--pi-ink);
	text-align     : center;
	background     : var(--pi-rule) center bottom / 3.4cm 7px no-repeat;
}
.page .kicker.plaque {
	margin         : 0 auto .3cm;
	padding        : .02cm .5cm 0;
	font-family    : 'IM Fell English SC', serif;
	font-size      : .42cm;
	font-weight    : normal;
	line-height    : 1.1em;
	letter-spacing : .12em;
	text-transform : none;
	background     : none;
	border         : solid transparent;
	border-width   : .5cm 1.05cm;
	border-image   : var(--pi-plaque) 40 92 fill / .5cm 1.05cm stretch;
}
.page .kicker + h1 { margin-top : 0; }

/* INTRO  ·  {{intro ...}} */
.page .intro {
	display       : block;     /* hbfm blocks are inline-block; column-span ignores those */
	column-span   : all;
	columns       : 2;
	column-gap    : .8cm;
	column-fill   : balance;
	margin-bottom : .4cm;
}

/* DROP CAP  ·  automatic after an H1, or {{dropcap ...}} / p.drop-cap.
   The wash is a translucent image: the paper (and any art behind it)
   shows straight through – there is no opaque patch to hide.            */
.page h1 + p::first-letter,
.page p.first-letter::first-letter,
.page p.drop-cap::first-letter,
.page .dropcap > p:first-of-type::first-letter {
	float                   : left;
	margin                  : -.02cm .12cm -.1cm -.2cm;
	padding                 : .14cm .2cm .06cm .2cm;
	font-family             : 'IM Fell English', serif;
	font-size               : 1.5cm;
	font-style              : normal;
	font-weight             : bold;
	line-height             : .86em;
	color                   : var(--pi-cap);
	background-color        : transparent;
	background-image        : var(--pi-capblot);
	background-position     : 50% 50%;
	background-size         : 132% 126%;
	background-repeat       : no-repeat;
	-webkit-background-clip : border-box;
	background-clip         : border-box;
}
.page .dropcap > p:first-of-type { text-indent : 0; }
/* PHB blocks are inline-block + break-inside:avoid, i.e. unsplittable: let prose flow */
.page .dropcap { display : block; break-inside : auto; }

/* RULE  ·  {{rule}}  thorn and star (default)
           {{rule,vine}} engraved vine · {{rule,knot}} · {{rule,barbed}}   */
.page .rule {
	display      : block;
	aspect-ratio : 300 / 31;
	max-height   : 1cm;
	margin       : .3cm auto;
	background   : var(--pi-p-rule-thorn) center / contain no-repeat;
}
.page .rule.vine   { aspect-ratio : 320 / 23; background-image : var(--pi-vine); }
.page .rule.knot   { aspect-ratio : 300 / 65; background-image : var(--pi-p-rule-knot); }
.page .rule.barbed { aspect-ratio : 300 / 51; background-image : var(--pi-p-rule-barbed); }

/* CARTOUCHE  ·  {{cartouche ... }} around a title.
   Drawn at its own proportions (stretching smears the engraving), so it
   holds one line: a short title, or an H1 plus a line of small caps.        */
.page .cartouche {
	display          : flex;
	flex-direction   : column;
	justify-content  : center;
	align-items      : center;
	column-span      : all;
	box-sizing       : border-box;
	width            : calc(100% + 1.2cm);
	margin           : -.3cm -.6cm .4cm;
	padding          : 0 16% .1cm;
	aspect-ratio     : 816 / 198;
	text-align       : center;
	background       : var(--pi-cartouche) center / 100% 100% no-repeat;
}
.page .cartouche :is(h1, h2) { margin : 0; font-size : 1.2cm; line-height : 1em; white-space : nowrap; }
.page .cartouche h1 + p::first-letter { all : unset; }
.page .cartouche p { margin : .05cm 0 0; text-indent : 0; font-family : 'IM Fell English SC', serif; font-size : .34cm; font-weight : normal; letter-spacing : .12em; }

/* WREATH  ·  {{wreath ... }}  oval thorn wreath with a ribbon.
   The first heading inside goes on the ribbon; an image inside fills the
   oval behind it, clipped to the wreath's opening (a portrait medallion,
   a chapter emblem). Anything else is centred under the ribbon.

     {{wreath
     ![](portrait.webp)
     ## Lady of Pain
     }}                                                                   */
.page .wreath {
	position        : relative;
	display         : block;
	column-span     : all;
	width           : var(--wreath-w, 11cm);
	max-width       : 100%;
	margin          : .2cm auto .5cm;
	aspect-ratio    : 380 / 278.5;
	text-align      : center;
	background      : var(--pi-p-wreath) center / 100% 100% no-repeat;
	break-inside    : avoid;
}
/* The ribbon crosses the middle of the opening, so a portrait has to put
   the face in the upper half: the image box runs from above the opening
   (the top thorns cover the overshoot) to its bottom, and is aligned to
   its top. A figure with the face in its upper third (most character art)
   lands with the face above the ribbon and the ribbon across the chest.
   Adjust per image:
     --wreath-focus  which part of the image shows when it is cropped
                     (object-position y: 0% top .. 100% bottom)          */
.page .wreath img {
	position        : absolute;
	top             : 10%;
	left            : 18%;
	z-index         : -1;
	width           : 64%;          /* a replaced element won't stretch between insets */
	height          : 79%;
	object-fit      : cover;
	object-position : 50% var(--wreath-focus, 0%);
	-webkit-clip-path : ellipse(50% 46% at 50% 54%);    /* the opening, a little taller at the top */
	clip-path       : ellipse(50% 46% at 50% 54%);
	-webkit-mask-image : none;
	mask-image      : none;
}
.page .wreath :is(h1, h2, h3, h4) {
	position        : absolute;
	top             : 50%;         /* the ribbon's centre line (measured on the art) */
	left            : 32%;
	right           : 32%;
	margin          : 0;
	font-size       : var(--wreath-title, .62cm);
	line-height     : 1;
	white-space     : nowrap;
	transform       : translateY(-50%);
}
.page .wreath p:has(img) { position : static; margin : 0; }
.page .wreath p:not(:has(img)) { position : absolute; top : 62%; left : 30%; right : 30%; margin : 0; text-indent : 0; font-size : .3cm; font-style : italic; }
.page .wreath:has(img) p:not(:has(img)) { top : 99%; left : 15%; right : 15%; font-size : .36cm; }     /* with a portrait, the subtitle goes under the wreath */
.page .wreath:has(img) { margin-bottom : 1.1cm; }
.page .wreath h1 + p::first-letter { all : unset; }

/* ORNAMENT  ·  {{orn ☠}} inline, takes the text colour */
.page .orn {
	font-family    : 'Planar Thorn', serif;
	font-style     : normal;
	line-height    : 1;
	vertical-align : -.08em;
	color          : var(--pi-ink);
}

/* CAPTION  ·  {{caption ...}} */
.page .caption {
	display     : block;
	font-family : 'IM Fell English', serif;
	font-size   : .28cm;
	font-style  : italic;
	line-height : 1.25em;
	color       : var(--pi-faint);
	text-indent : 0;
}
.page .caption p { text-indent : 0; }


/* ARTWORK _________________________________________________________

   Every image is graded and multiplied into the paper. Masking is opt-in.

   THE MASK
   .watercolor-mask gives the art a torn-paper edge. The picture keeps
   almost all of its box; only a rim of ~1-3% is ragged.
       --pi-wc-shape  the torn edge: plain vector polygons, no SVG filters,
                      so it prints as sharply as it displays. No intrinsic
                      size: it stretches to the box.
                      wc-1 torn paper · wc-2 rough tear
                      wc-3 bleed: the paint thins out into the paper over
                      the outer fifth of the box; no frame (a soft alpha
                      bitmap, the one mask here that is not a polygon)
       ink-frame      (block form) hand-inked border over the art
       --pi-wc-fade   optional directional fade (fade-left/-right/-top/-bottom)
                      for art that should bleed into the text side.

   Prefer the block form for print:  {{watercolor-mask,wide,height:9cm ... }}
   The wrapper takes the fade, the image the edge: one mask per element.
   ![](url){watercolor-mask} on a bare image works too; adding a fade there
   needs mask-composite, which some PDF exporters drop.                   */

.page img {
	filter         : var(--pi-art-grade);
	mix-blend-mode : var(--pi-art-blend);
}

/* NB: Blank's stock-stamp rule  [class*='watercolor']  substring-matches
   this class and would force position:absolute, 2000px x 2000px and a
   coloured background. Reset all of it here (same specificity, later).  */
.page .watercolor-mask,
.page .plate {
	position         : relative;
	z-index          : auto;
	width            : auto;
	height           : auto;
	background-color : transparent;
	background-size  : auto;
	--pi-wc-shape : var(--pi-wc-1);
	--pi-wc-fade  : none;
	-webkit-mask-image  : var(--pi-wc-shape);
	mask-image          : var(--pi-wc-shape);
	-webkit-mask-size   : 100% 100%;
	mask-size           : 100% 100%;
	-webkit-mask-repeat : no-repeat;
	mask-repeat         : no-repeat;
}
.page .wc-2 { --pi-wc-shape : var(--pi-wc-2); }
.page .wc-3 { --pi-wc-shape : var(--pi-wc-3); }

/* fade toward the side the text is on */
.page .fade-left   { --pi-wc-fade : linear-gradient(to right,  transparent, #000 30%); }
.page .fade-right  { --pi-wc-fade : linear-gradient(to left,   transparent, #000 30%); }
.page .fade-top    { --pi-wc-fade : linear-gradient(to bottom, transparent, #000 30%); }
.page .fade-bottom { --pi-wc-fade : linear-gradient(to top,    transparent, #000 30%); }

/* An <img> with a fade needs both layers intersected on one element.
   mask-composite is the least print-safe piece of all this (WebKit's PDF
   path has dropped it); the block form below avoids it.                 */
.page img.watercolor-mask:is(.fade-left, .fade-right, .fade-top, .fade-bottom) {
	-webkit-mask-image     : var(--pi-wc-shape), var(--pi-wc-fade);
	mask-image             : var(--pi-wc-shape), var(--pi-wc-fade);
	-webkit-mask-composite : source-in;
	mask-composite         : intersect;
}

/* BLOCK FORM  ·  one mask per element, nothing to composite:
   the wrapper carries the fade (if any) and does the multiply into the
   paper; the image inside carries the torn edge.                        */
.page :is(div, span).watercolor-mask,
.page .plate {
	position            : relative;
	display             : block;
	height              : 9cm;
	break-inside        : avoid;
	-webkit-mask-image  : var(--pi-wc-fade);
	mask-image          : var(--pi-wc-fade);
	mix-blend-mode      : var(--pi-art-blend);
}
.page .plate.wide,
.page div.watercolor-mask.wide { column-span : all; width : auto; }   /* auto, not PHB's 100%, so negative margins bleed */
.page :is(div, span).watercolor-mask img,
.page .plate img {
	position        : absolute;
	inset           : 0;
	z-index         : 0;
	width           : 100%;
	height          : 100%;
	object-fit      : cover;
	object-position : var(--art-x, 50%) var(--art-y, 50%);
	-webkit-mask-image  : var(--pi-wc-shape);
	mask-image          : var(--pi-wc-shape);
	-webkit-mask-size   : 100% 100%;
	mask-size           : 100% 100%;
	-webkit-mask-repeat : no-repeat;
	mask-repeat         : no-repeat;
	mix-blend-mode  : normal;
}
.page :is(div, span).watercolor-mask p,
.page .plate p { margin : 0; }

/* INK FRAME  ·  add  ink-frame  to a block-form mask for the framed panel
   of the references: the art fills a ruled pen border, the lines crossing
   at the corners, and the paint doesn't quite respect the line: in places
   it runs a few pixels past it, in others it stops short and a sliver of
   paper shows inside the frame.

   The mask is five layers, unioned: a rectangle for the middle and a
   26px strip per side whose ragged edge wanders around the line (which
   sits 11.7px inside the box, leaving the paint room to spill). The strips have a fixed depth and stretch only along
   their length, so the wander is the same few pixels on any panel size.
     + wc-2   a second set of edges, so two panels on a spread differ
     + clean  paint stops dead on the line all round
     + torn   the ragged torn-paper rim inside the frame instead        */
.page :is(div, span).watercolor-mask.ink-frame:not(.torn) img {
	--sp-t : var(--pi-spill-t); --sp-r : var(--pi-spill-r); --sp-b : var(--pi-spill-b); --sp-l : var(--pi-spill-l);
	-webkit-mask-image    : linear-gradient(#000, #000), var(--sp-t), var(--sp-r), var(--sp-b), var(--sp-l);
	mask-image            : linear-gradient(#000, #000), var(--sp-t), var(--sp-r), var(--sp-b), var(--sp-l);
	-webkit-mask-size     : calc(100% - 48px) calc(100% - 48px), calc(100% - 23.4px) 26px, 26px calc(100% - 23.4px), calc(100% - 23.4px) 26px, 26px calc(100% - 23.4px);
	mask-size             : calc(100% - 48px) calc(100% - 48px), calc(100% - 23.4px) 26px, 26px calc(100% - 23.4px), calc(100% - 23.4px) 26px, 26px calc(100% - 23.4px);
	-webkit-mask-position : center, 11.7px 0, 100% 11.7px, 11.7px 100%, 0 11.7px;
	mask-position         : center, 11.7px 0, 100% 11.7px, 11.7px 100%, 0 11.7px;
	-webkit-mask-repeat   : no-repeat;
	mask-repeat           : no-repeat;
}
.page :is(div, span).watercolor-mask.ink-frame.wc-2:not(.torn) img {
	--sp-t : var(--pi-spill2-t); --sp-r : var(--pi-spill2-r); --sp-b : var(--pi-spill2-b); --sp-l : var(--pi-spill2-l);
}
.page :is(div, span).watercolor-mask.ink-frame.clean img {
	-webkit-mask-image : none;
	mask-image         : none;
	-webkit-clip-path  : inset(11.7px);
	clip-path          : inset(11.7px);
}
.page :is(div, span).watercolor-mask.ink-frame::after {
	content        : '';
	position       : absolute;
	inset          : 4px;
	z-index        : 1;
	box-sizing     : border-box;
	border         : 22px solid transparent;
	border-image   : var(--pi-ink-frame) 40 / 22px stretch;
	pointer-events : none;
}

/* FLOAT  ·  text wraps the silhouette itself, not the bounding box.
   shape-outside reads the same mask image as the art, so the wrap line
   follows the painted edge. Give it a width and height.                 */
.page .wc-float-left,
.page .wc-float-right {
	--pi-wc-shape          : var(--pi-wc-1);
	width                  : var(--wc-w, 60%);
	height                 : var(--wc-h, 6cm);
	object-fit             : cover;
	shape-outside          : var(--pi-wc-shape);
	shape-image-threshold  : .3;
	shape-margin           : .18cm;
}
.page .wc-float-left  { float : left;  margin : 0 0 0 -.6cm; }
.page .wc-float-right { float : right; margin : 0 -.6cm 0 0; }
.page .wc-float-left.wc-2,  .page .wc-float-right.wc-2  { --pi-wc-shape : var(--pi-wc-2); }
.page .wc-float-left.wc-3,  .page .wc-float-right.wc-3  { --pi-wc-shape : var(--pi-wc-3); }

/* BEHIND  ·  a faint scene underneath the text column(s). Place it with
   inline styles; .page is a stacking context, so z-index:-1 lands above
   the paper but below the text.                                          */
.page .wc-behind {
	position : absolute;
	z-index  : -1;
	opacity  : var(--wc-opacity, .45);
}

/* stock watercolour masks → grey ink washes */
.page [class*='watercolor']:not(.watercolor-mask) {
	z-index          : -2;
	mix-blend-mode   : multiply;
	opacity          : .4;
	background-color : var(--HB_Color_WatercolorStain);
}


/* NOTE  ·  sketched box ___________________________________________ */
/* border-box sizing keeps the drawn border inside the column            */
/* A box is two things drawn separately, as on a real page: a pen frame
   (strokes that cross at the corners) and a grey wash laid inside it that
   doesn't quite keep to the line. The wash is a pseudo-element under the
   text with a torn-edge mask; the frame is the box's own border-image and
   is not masked, so its corners overshoot and nothing clips its lines.    */
.page .note,
.page .monster.frame {
	position         : relative;
	box-sizing       : border-box;
	background       : none;                 /* the theme's fill and texture are grey on parchment */
	border           : 8px solid transparent;
	border-image     : var(--pi-box-frame) 40 / 16px / 5px stretch;
	box-shadow       : none;
}
.page .note > :first-child,
.page .monster.frame > :first-child { margin-top : 0; }
.page .note::before,
.page .monster.frame::before {
	content          : '';
	position         : absolute;
	inset            : -5px;
	z-index          : -1;
	pointer-events   : none;
	background       :
		radial-gradient(ellipse 60% 45% at 22% 18%, var(--pi-wash), transparent 70%),
		radial-gradient(ellipse 55% 50% at 80% 78%, var(--pi-wash), transparent 72%),
		var(--pi-wash);
	-webkit-mask     : var(--pi-box-edge) 0 0 / 100% 100% no-repeat;
	mask             : var(--pi-box-edge) 0 0 / 100% 100% no-repeat;
}
.page .note {
	margin-block     : .34cm;
	padding          : .12cm .2cm .16cm;
	font-family      : 'IM Fell English', 'Georgia', serif;
	font-size        : .33cm;
}
.page .note h5 { margin-bottom : .08cm; font-size : .36cm; }
.page .note :is(h3, h4) { margin-top : 0; }
.page .note p  { text-indent : 0; }

/* DESCRIPTIVE  ·  read-aloud: the one place italics belong ________ */
.page .descriptive {
	margin-block : .3cm;
	padding      : .22cm .3cm .22cm .45cm;
	font-family  : 'IM Fell English', serif;
	font-size    : .36cm;
	font-style   : italic;
	background   : linear-gradient(90deg, var(--pi-wash-2), transparent 80%);
	box-sizing   : border-box;
	width        : auto;
	margin-inline : 0;
	background-clip : padding-box;
	border       : 0 solid transparent;
	border-left-width : 10px;
	border-image : var(--pi-box-frame) 40 / 0 0 0 16px / 0 0 0 4px stretch;      /* the frame's left-hand pen strokes only */
	box-shadow   : none;
}
.page .descriptive p { line-height : 1.32em; }


/* TABLES __________________________________________________________
   Hand-ruled: a pen stroke above and below (drawn, not a CSS border, so
   it wobbles and overshoots like the art frames), a lighter one under the
   head, and a pass of grey wash on every other row in place of flat
   stripes. Three washes rotate so neighbouring stripes differ.           */
.page table {
	font-size         : .32cm;
	line-height       : 1.22em;
	border            : 0;
	border-collapse   : collapse;
	background        :
		var(--pi-stroke-1) center top    / calc(100% + 10px) 8px no-repeat,
		var(--pi-stroke-2) center bottom / calc(100% + 10px) 8px no-repeat;
}
.page table thead th {
	padding           : .14cm .1cm .08cm;
	font-family       : 'IM Fell English SC', serif;
	font-size         : .31cm;
	font-weight       : normal;
	letter-spacing    : .05em;
	color             : var(--pi-ink);
	border-bottom     : 0;
	background        : var(--pi-stroke-2) center bottom / 100% 5px no-repeat;
}
.page table tbody td { padding : .05cm .12cm; vertical-align : top; }
.page table tbody tr:first-child td { padding-top : .09cm; }
.page table tbody tr:last-child  td { padding-bottom : .14cm; }
.page table tbody tr:nth-child(odd)  { background : none; }
.page table tbody tr:nth-child(odd)  { background : var(--pi-row-1) 0 0 / 100% 100% no-repeat; }
.page table tbody tr:nth-child(4n+3) { background-image : var(--pi-row-2); }
.page table tbody tr:nth-child(6n+5) { background-image : var(--pi-row-3); }
/* a table whose first column is a die roll: the numbers in the thorn hand */
.page table td:first-child:is([align='center']),
.page table td:first-child[style*='center'] { font-family : 'Planar Thorn', 'IM Fell English', serif; font-size : .36cm; color : var(--pi-ink); }


/* MONSTER STAT BLOCK ______________________________________________
   Frame and wash: see NOTE above.                                      */
.page .monster.frame {
	width            : auto;
	margin           : .3cm 0 .4cm;
	padding          : .06cm .16cm .12cm;
}
.page .monster h2 { font-size : .7cm; margin-bottom : .02cm; }
.page .monster h2 + p { font-size : .31cm; color : var(--pi-faint); }
.page .monster h3 {
	margin         : .16cm 0 .1cm;
	padding-bottom : .06cm;
	font-family    : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size      : .5cm;
	letter-spacing : .02em;
	text-transform : none;
	background     : var(--pi-stroke-2) left bottom / 100% 5px no-repeat;
	border-bottom  : 0;
}
.page .monster :is(dt, strong) { color : var(--pi-ink); }
.page .monster p + p,
.page .monster :is(ul, ol, dl, table, hr, h3) + p { text-indent : 0; }
.page .monster p + p { margin-top : .12cm; }
/* the ability scores: a ruled line of six, not a zebra table */
.page .monster table { background : none; }
.page .monster table thead th { padding-top : .02cm; background-size : 100% 4px; }
.page .monster table tbody tr:nth-child(n) { background : none; }
.page .monster table tbody td,
.page .monster table td:first-child { padding : .03cm .04cm; font-family : inherit; font-size : inherit; color : inherit; }
.page .monster hr {
	height            : 8px;
	margin            : .08cm 0;
	visibility        : visible;
	background        : var(--pi-stroke-1) center / 100% 100% no-repeat;
	border            : 0;
	opacity           : .8;
	-webkit-clip-path : none;
	clip-path         : none;
}


/* TABLE OF CONTENTS _______________________________________________ */
.page .toc h1 { text-align : center; }
.page .toc h3 { font-family : 'IM Fell English', serif; font-size : .37cm; font-weight : bold; letter-spacing : 0; background : none; }
.page .toc h4 { font-family : 'IM Fell English SC', serif; font-weight : normal; font-size : .36cm; }
.page .toc ul span:first-child::after { border-bottom : .04cm dotted var(--pi-faint); }
.page .toc ul span:last-child { font-family : 'Planar Thorn', 'IM Fell English SC', serif; color : var(--pi-ink); }
.page .toc a { text-decoration : none; }


/* CODE ____________________________________________________________ */
.page code {
	font-size        : .32cm;
	color            : var(--pi-ink);
	background-color : var(--pi-wash-2);
}


/* STOCK COVERS  ·  re-ink the PHB cover snippets ___________________ */
.page:has(:is(.frontCover, .insideCover, .backCover)) h1 {
	font-family         : 'Planar Thorn', 'IM Fell English SC', serif;
	font-size           : 1.9cm;
	line-height         : 1.02em;
	color               : var(--pi-ink);
	-webkit-text-stroke : 0;
}
.page:has(:is(.frontCover, .insideCover, .backCover)) h2 {
	font-family         : 'IM Fell English SC', serif;
	font-weight         : normal;
	color               : var(--pi-ink);
	-webkit-text-stroke : 0;
}
.page:has(:is(.frontCover, .insideCover)) hr {
	height           : 14px;
	background-image : var(--pi-rule);
	filter           : none;
}
.page:has(.frontCover) .footnote {
	font-family         : 'IM Fell English', serif;
	font-style          : italic;
	color               : var(--pi-text);
	-webkit-text-stroke : 0;
}
.page:has(:is(.frontCover, .backCover)) .pageNumber { display : none; }


/* PRINT ___________________________________________________________
   Homebrewery pages are US Letter (215.9 x 279.4 mm). Pin the sheet so the
   print dialog can't leave a strip under the background or crop the art.
   The torn-edge mask leaves the very edge of the sheet unprinted (white);
   use  \page {untorn}  if you'd rather print to bleed.                    */
@page { size : 215.9mm 279.4mm; margin : 0; }
@media print {
	* { -webkit-print-color-adjust : exact; print-color-adjust : exact; }
}
